class Strings(val language: String) {
    operator fun get(t: T) = when (language) { "kk" -> t.kk; "en" -> t.en; else -> t.ru }
    fun failure(f: Failure) = get(when(f) {
        Failure.EMPTY -> T.EmptyError; Failure.FORMAT -> T.FormatError; Failure.INCOMPLETE -> T.IncompleteError
        Failure.CORRUPTED -> T.CorruptError; Failure.TOO_LONG -> T.LongError; Failure.PASSWORD_SHORT -> T.PasswordError
        Failure.AUTHENTICATION -> T.AuthError; Failure.STORAGE -> T.StorageError; Failure.QR_TOO_LONG -> T.QrError; Failure.BIOMETRIC -> T.BiometricUnavailable
    })
}
val LocalStrings = staticCompositionLocalOf { Strings("ru") }
